  624:                 // carries its exact bytes, so the payload paths open the
  625:                 // real file and a capable destination creates the real name.
  626:                 let raw_relative_path = crate::raw_name::raw_relative_bytes(&entry.relative_path);
  627:                 let absolute = entry.absolute_path.clone();
  628: 
  629:                 if let Err(err) = std::fs::File::open(&absolute) {
  630:                     match err.kind() {
  631:                         ErrorKind::PermissionDenied => {
  632:                             record_unreadable_entry(&unreadable, &rel, "permission denied");
  633:                             return Ok(());
  634:                         }
  635:                         ErrorKind::NotFound => {
  636:                             record_unreadable_entry(&unreadable, &rel, "not found");
  637:                             return Ok(());
  638:                         }
  639:                         _ => {
  640:                             return Err(eyre!(format!(
  641:                                 "manifest open {}: {}",
  642:                                 absolute.display(),
  643:                                 err
  644:                             )));
  645:                         }
  646:                     }
  647:                 }
  648: 
  649:                 let mtime = crate::wire_metadata::mtime_seconds(&entry.metadata).unwrap_or(0);
  650:                 let permissions = crate::wire_metadata::permissions_mode(&entry.metadata);
  651:                 let Some(mut header) = file_header_with_windows_metadata_policy(
