  653:                     size,
  654:                     mtime,
  655:                     permissions,
  656:                     &absolute,
  657:                     &unreadable,
  658:                     preserve_windows_metadata,
  659:                     crate::windows_metadata::read_manifest,
  660:                 ) else {
  661:                     return Ok(());
  662:                 };
  663:                 header.raw_relative_path = raw_relative_path;
  664:                 phase_probe.measure(LocalPhase::EnumerateBackpressure, || {
  665:                     manifest_tx
  666:                         .blocking_send(header)
  667:                         .map_err(|_| eyre!("failed to queue manifest entry"))
  668:                 })?;
  669:                 enumerated += 1;
  670:                 // R46-F4: liveness to stderr, never stdout — the CLI's
  671:                 // `--json` modes own stdout. clp-1: with a progress sink
  672:                 // attached it rides the lane instead of stderr.
  673:                 heartbeat.tick(enumerated);
