  685:             // EnumerateBackpressure. `saturating_sub` because the two clocks
  686:             // are read independently; a negative remainder would mean the
  687:             // sends outlasted the walk, which is a measurement fault, not a
  688:             // negative duration to propagate.
  689:             let backpressure = phase_probe.total(LocalPhase::EnumerateBackpressure);
  690:             phase_probe.record(
  691:                 LocalPhase::Enumerate,
  692:                 started.elapsed().saturating_sub(backpressure),
  693:             );
  694:         }
